const SYNCED=new Set(['voice','voice_pt-PT','voice_en-US','autoLang','engine','cacheBehind','cacheAhead','autoplayBuffer','prefetchMode','speed','volume','theme','mode','font','partialRecording','cloudCopy','uiReady','uiLocal','uiStripes','uiEta','uiWord','uiScroll','uiContrast','keepAwake']);
let pendingSync={},syncTimer;
const store = (key,value) => { try { localStorage.setItem('lectoria_'+key,String(value)); } catch {} if(SYNCED.has(key)&&state.user){pendingSync[key]=String(value);clearTimeout(syncTimer);syncTimer=setTimeout(()=>{const body=pendingSync;pendingSync={};api('settings',{method:'PUT',body:JSON.stringify(body)}).catch(()=>{});},800);} };
async function pullSettings(){try{const remote=await api('settings');for(const [key,value] of Object.entries(remote))if(SYNCED.has(key))localStorage.setItem('lectoria_'+key,value);if(!Object.keys(remote).length){const mine={};for(const key of SYNCED){const value=localStorage.getItem('lectoria_'+key);if(value!=null)mine[key]=value;}if(Object.keys(mine).length)api('settings',{method:'PUT',body:JSON.stringify(mine)}).catch(()=>{});}state.font=Number(stored('font',20));applyAppearance();if(typeof showSpeed==='function'){$('speed').value=stored('speed','1');if(!$('speed').value)$('speed').value='1';showSpeed();setVolume(stored('volume','80'),false);$('engine').value=stored('engine','host');engineHint();}}catch{}}
const state = { user:null, docs:[], doc:null, section:0, chunks:[], index:0, offset:0, position:0, status:'idle', generation:0, controller:null, url:null, blob:null, cache:new Map(), page:1, selection:null, font:Number(stored('font',20)), bookRequest:0, blogPage:1, postRequest:0, jobs:[], speeds:{}, cloud:false, jobTimer:null, voices:[], queue:[], playlists:[], playlist:null, action:null, serverReady:new Set(), cacheCheck:0, coverBust:{}, liveSpeed:{} };
const coverUrl=(doc,kind='documents')=>doc.cover==='own'?`./api/${kind}/${doc.id}/cover${state.coverBust[doc.id]?'?v='+state.coverBust[doc.id]:''}`:doc.cover&&/^https:/.test(doc.cover)?doc.cover:null;
const audio = $('audio'); let toastTimer, progressTimer;
async function api(route, options={}) {
  const response = await fetch('./api/'+route,{...options,headers:{...(options.body && !(options.body instanceof Blob)?{'Content-Type':'application/json'}:{}),...options.headers}});
  if(!response.ok){const data=await response.json().catch(()=>({}));const e=new Error(data.error || 'Não foi possível concluir o pedido.');e.status=response.status;if(response.status===401 && state.user){state.user=null;updateAccount();}throw e;}
  return response.headers.get('content-type')?.includes('audio/')?response.blob():response.json();
}
