function changeView(name){const hash='#'+name+(name==='reader'&&state.doc?'/'+state.doc.id:'');if(location.hash!==hash)history.pushState(null,'',hash);document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==name+'-view');document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('view-label').textContent=({home:'Visão geral',kavita:'Biblioteca Kavita',blogs:'Blogues',shelf:'A minha estante',queue:'Fila',playlists:'Playlists',audio:'Áudios',write:'Escrever texto',settings:'Definições',reader:'Leitura'})[name];document.body.classList.remove('menu-open');$('menu-toggle').setAttribute('aria-expanded','false');window.scrollTo({top:0,behavior:'instant'});if(name==='kavita'&&state.user&&!$('library-select').value)loadLibraries();if(name==='shelf')refreshShelf();if(name==='blogs'&&!$('blog-select').value)loadBlogs();if(name==='audio')refreshJobs();if(name==='settings')renderSettings();if(name==='queue')renderQueue();if(name==='playlists')renderPlaylists();}
function applyAppearance(){document.documentElement.dataset.theme=stored('theme',matchMedia('(prefers-color-scheme: light)').matches?'light':'dark');const mode=stored('mode','standard');document.body.classList.toggle('mode-clean',mode==='clean');document.body.classList.toggle('mode-reading',mode==='reading');$('clean-mode').setAttribute('aria-pressed',mode==='clean');$('reading-mode').setAttribute('aria-pressed',mode==='reading');$('theme-toggle').setAttribute('aria-label',document.documentElement.dataset.theme==='dark'?'Ativar tema claro':'Ativar tema escuro');document.documentElement.style.setProperty('--reading-font',Math.min(30,Math.max(16,state.font))+'px');for(const [key,cls] of [['uiReady','no-ready'],['uiLocal','no-local'],['uiStripes','no-stripes'],['uiEta','no-eta'],['uiWord','no-word']])document.body.classList.toggle(cls,stored(key,'1')!=='1');document.body.dataset.contrast=stored('uiContrast','normal');}
