$('job-filter').onchange=$('job-search').oninput=()=>{state.jobsSig=null;renderJobs();};
$('download-audio').onclick=()=>{if(!state.blob)return toast('Ouve uma passagem primeiro para guardar o seu áudio.');const link=document.createElement('a');link.href=state.url;link.download='lectoria-'+(state.section+1)+'-'+(state.index+1)+'.wav';link.click();};
