window.addEventListener('pagehide',()=>{if(state.user&&state.doc){const payload=JSON.stringify({section:state.section,position:Math.floor(state.position)});fetch('./api/documents/'+state.doc.id+'/progress',{method:'PUT',headers:{'Content-Type':'application/json'},body:payload,keepalive:true}).catch(()=>{});}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
async function applyHash(){const [name,id]=location.hash.slice(1).split('/');if(name==='reader'&&/^[a-f0-9]{32}$/.test(id||'')){if(state.doc?.id===id){changeView('reader');return;}if(state.user){try{await openSaved(id);return;}catch{}}}if(['home','kavita','blogs','shelf','queue','playlists','audio','write','settings'].includes(name)&&!(name==='reader'))changeView(name);else if(name!=='reader')changeView('home');}
window.addEventListener('popstate',()=>applyHash());
async function start(){renderDocuments();try{state.user=await api('session');updateAccount();await pullSettings();await Promise.all([refreshShelf(),loadVoices(),loadLists()]);renderDocuments();updateUpNext();}catch{updateAccount();}await applyHash();}
start();
